import {mountShell} from '../shared/shell.js?v=0.16.0';
import {escapeHtml as e,downloadText,writeStore} from '../shared/utils.js?v=0.16.0';
import {PEOPLE,SKILLS,DEFAULT_TRAINING,workloadFor} from './engine.js?v=0.16.0';
import {KEY,initial,validate,pin,replay,template,portable,parse,markdown} from './state.js?v=0.16.0';
mountShell({active:'knowledge'});
const $=s=>document.querySelector(s),clone=structuredClone,n=(v,d=1)=>Number(v).toFixed(d),uid=()=>crypto.randomUUID();
let s=initial(),past=[],result,base,paused=false,recovery=null;
try{const raw=localStorage.getItem(KEY);if(raw){recovery=raw;s=validate(JSON.parse(raw));recovery=null;}}catch{paused=true;}
function status(message){$('#status').textContent=message;$('#recovery').hidden=!paused;}
function save(){if(paused){status('Saving paused. Keep a recovery copy, or explicitly save this plan instead.');return;}if(!writeStore(KEY,s))status('Saving unavailable. Export this plan.');}
function compute(){({current:result,baseline:base}=replay(s));}
function change(fn,message){const before=clone(s);try{fn();s=validate(s);past.push(before);past=past.slice(-35);compute();render();status(message||'Both plans replayed with the same demand and absences.');save();return true;}catch(error){s=before;render();status(error.message);return false;}}
const options=(items,value)=>items.map((name,i)=>`<option value="${i}" ${i===value?'selected':''}>${e(name)}</option>`).join('');
function chart(){const rows=result.history,b=base?.history,max=Math.max(1,...rows.map(r=>r.totalBacklog),...(b||[]).map(r=>r.totalBacklog)),x=i=>30+i/23*510,y=v=>180-v/max*150,path=arr=>arr.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r.totalBacklog)}`).join(' ');$('#chart').innerHTML=`<svg viewBox="0 0 560 215" aria-hidden="true"><line x1="30" y1="180" x2="540" y2="180" stroke="var(--line)"/><text x="2" y="29">${n(max,0)}</text><text x="2" y="185">0</text>${b?`<path d="${path(b)}" fill="none" stroke="var(--line-strong)" stroke-width="2" stroke-dasharray="5 4"/>`:''}<path d="${path(rows)}" fill="none" stroke="var(--accent)" stroke-width="3"/><line x1="${x(s.week-1)}" y1="20" x2="${x(s.week-1)}" y2="180" stroke="var(--warn)"/><text x="30" y="207">W1</text><text x="510" y="207">W24</text></svg>`;$('#chart').setAttribute('aria-label',`Waiting after 24 weeks: ${n(result.final.totalBacklog)}${base?`; baseline ${n(base.final.totalBacklog)}`:''}.`);}
function week(){const row=result.history[s.week-1];$('#skills').innerHTML=PEOPLE.map((p,i)=>`<tr><th scope="row">${p}${!row.present[i]?'<small>away</small>':''}</th>${SKILLS.map((sk,j)=>`<td><button id="skill-${i}-${j}" class="skill-cell" data-person="${i}" data-skill="${j}" aria-label="${p}, ${sk.name}, starting ${n(s.skills[i][j]*100,0)} percent. Cycle by 25 points." style="--level:${s.skills[i][j]*100}%"><strong>${n(s.skills[i][j]*100,0)}%</strong><span>→ ${n(row.levels[i][j]*100,0)}%</span></button></td>`).join('')}<td><select id="focus-${i}" data-focus="${i}" aria-label="Work assignment for ${p}"><option value="-1" ${s.focus[i]===-1?'selected':''}>Any work</option>${options(SKILLS.map(k=>k.name),s.focus[i])}</select></td></tr>`).join('');$('#grid-week').textContent=s.week;$('#week').value=s.week;$('#week-label').value=s.week;
 $('#week-detail').innerHTML=`${row.coachingEvents.length?row.coachingEvents.map(c=>`<p class="event ${c.blocked?'blocked':c.limited?'limited':''}"><b>${PEOPLE[c.mentor]} → ${PEOPLE[c.learner]} · ${SKILLS[c.skill].name}</b><br>${c.blocked?e(c.blocked)+': no time used.':`${n(c.actual*100,0)}% of each person’s week${c.limited?` (requested ${n(c.fraction*100,0)}%; time shared with another period)`:''}. ${n(c.gain*100)} skill points gained at week end${c.gain===0?'; no starting skill advantage':''}.`}</p>`).join(''):'<p>No coaching scheduled this week.</p>'}<p class="hint">Time per person: work / coaching / idle. Gains appear after this week’s output.</p>${PEOPLE.map((p,i)=>{const work=row.allocations.filter(a=>a.person===i).reduce((v,a)=>v+a.time,0),coached=row.coachingTime[i];return `<div class="person-time"><b>${p}</b> · ${row.present[i]?`${n(work*100,0)}% / ${n(coached*100,0)}% / ${n(row.idle[i]*100,0)}%`:'away'}<div class="time-bar" aria-hidden="true"><span class="work" style="width:${work*100}%"></span><span class="coach" style="width:${coached*100}%"></span></div></div>`;}).join('')}<div>${SKILLS.map((k,j)=>`<p><b>${k.name}</b>: ${n(row.demand[j])} arrived · ${n(row.output[j])} completed · ${n(row.backlog[j])} waiting</p>`).join('')}</div>`;chart();}
function render(){const active=document.activeElement?.id,scroll=$('#schedule').scrollLeft,p=s.sessions.find(x=>x.id===s.selected);$('#scenario').value=s.scenario;$('#selected').innerHTML=s.sessions.map((x,i)=>`<option value="${e(x.id)}" ${x.id===s.selected?'selected':''}>${i+1}. ${PEOPLE[x.mentor]} → ${PEOPLE[x.learner]} · ${SKILLS[x.skill].name}</option>`).join('');$('#selected').disabled=!p;$('#remove').disabled=!p;$('#add').disabled=s.sessions.length>=6;$('#editor').hidden=!p;
 if(p){$('#mentor').innerHTML=options(PEOPLE,p.mentor);$('#learner').innerHTML=options(PEOPLE,p.learner);$('#skill').innerHTML=options(SKILLS.map(k=>k.name),p.skill);for(const id of ['start','duration'])$('#'+id).value=p[id];$('#fraction').value=Math.round(p.fraction*100);$('#enabled').checked=p.enabled;$('#start').max=25-p.duration;}
 $('#schedule').innerHTML=s.sessions.length?`<div class="schedule-inner">${s.sessions.map((x,i)=>`<div class="session-label">${i+1}. ${PEOPLE[x.mentor]} → ${PEOPLE[x.learner]} · ${SKILLS[x.skill].name} · ${n(x.fraction*100,0)}% each</div><div class="session-track"><button id="period-${e(x.id)}" class="training-block ${x.id===s.selected?'selected':''} ${x.enabled?'':'off'}" data-period="${e(x.id)}" style="left:${(x.start-1)/24*100}%;width:${x.duration/24*100}%" aria-label="Move coaching ${i+1}, ${PEOPLE[x.mentor]} to ${PEOPLE[x.learner]}, weeks ${x.start} to ${x.start+x.duration-1}">W${x.start}–${x.start+x.duration-1}</button></div>`).join('')}<div class="timeline-ticks"><span>W1</span><span>6</span><span>12</span><span>18</span><span>24</span></div></div>`:'<p style="padding:12px">No coaching. People can still learn through their work.</p>';$('#schedule').scrollLeft=scroll;
 $('#absences').innerHTML=s.absences.map(a=>`<div class="absence-row"><label>Person<select id="away-${e(a.id)}-person" data-away="${e(a.id)}" data-field="person">${options(PEOPLE,a.person)}</select></label><label>From<input id="away-${e(a.id)}-from" data-away="${e(a.id)}" data-field="from" type="number" min="1" max="24" value="${a.from}"></label><label>Through<input id="away-${e(a.id)}-to" data-away="${e(a.id)}" data-field="to" type="number" min="${a.from}" max="24" value="${a.to}"></label><button data-remove-away="${e(a.id)}">Remove ${PEOPLE[a.person]}’s absence</button></div>`).join('')||'<p>No absences.</p>';$('#add-absence').disabled=s.absences.length>=8;
 $('#demand').innerHTML=SKILLS.map((k,j)=>`<div class="demand-row"><span>${k.name}</span>${['before','after'].map(t=>`<label>${t==='before'?'Initial':'Later'}<input id="demand-${t}-${j}" data-demand="${t}" data-skill="${j}" aria-label="${k.name} ${t==='before'?'initial':'later'} weekly demand" type="number" min="0" max="4" step=".05" value="${s.workload[t][j]}"></label>`).join('')}</div>`).join('');$('#change-week').value=s.workload.changeWeek;
 $('#undo').disabled=!past.length;$('#pin').textContent=s.baseline?'Replace baseline':'Pin baseline';$('#decision').value=s.decision;$('#delivered').textContent=n(result.final.delivered);$('#backlog').textContent=n(result.final.totalBacklog);$('#coaching').textContent=n(result.final.learningTime);$('#coverage').textContent=SKILLS.map((_,j)=>result.final.levels.filter((r,p)=>result.final.present[p]&&r[j]>=.6).length).join(' / ');$('#delta').textContent=base?`${n(result.final.delivered-base.final.delivered)} vs baseline`:'Pin a plan to compare';
 const same=!s.baseline||JSON.stringify(s.skills)===JSON.stringify(s.baseline.skills);$('#comparison').innerHTML=base?`Solid: current. Dashed: pinned plan. Same demand and absences.${same?' Starting knowledge matches.':' <strong class="warning">Starting knowledge differs; this is not a coaching-only comparison.</strong>'}`:'Pin a plan before changing coaching or assignments. Each replay uses the same demand and absences.';$('#compare-table').innerHTML=base?`<table class="comparison-table"><thead><tr><th>After 24 weeks</th><th>Current</th><th>Pinned</th></tr></thead><tbody><tr><th>Completed</th><td>${n(result.final.delivered)}</td><td>${n(base.final.delivered)}</td></tr>${SKILLS.map((k,j)=>`<tr><th>${k.name} waiting</th><td>${n(result.final.backlog[j])}</td><td>${n(base.final.backlog[j])}</td></tr>`).join('')}<tr><th>Coaching time</th><td>${n(result.final.learningTime)}</td><td>${n(base.final.learningTime)}</td></tr></tbody></table>`:'';week();if(active)document.getElementById(active)?.focus({preventScroll:true});$('#recovery').hidden=!paused;}
$('#skills').onclick=event=>{const b=event.target.closest('[data-person]');if(b)change(()=>{const {person:p,skill:j}=b.dataset;s.skills[p][j]=s.skills[p][j]>=1?0:Math.min(1,Math.round((s.skills[p][j]+.25)*100)/100);},'Starting knowledge changed; this is an assumption, not free training.');};
$('#skills').onchange=event=>{if(event.target.dataset.focus!==undefined)change(()=>s.focus[+event.target.dataset.focus]=+event.target.value);};
for(const id of ['mentor','learner','skill','start','duration','fraction','enabled'])$('#'+id).onchange=event=>{const value=id==='enabled'?event.target.checked:+event.target.value;change(()=>{const p=s.sessions.find(x=>x.id===s.selected);p[id]=id==='fraction'?value/100:value;if(id==='duration')p.start=Math.min(p.start,25-p.duration);});};
$('#selected').onchange=event=>{s.selected=event.target.value;render();save();};$('#add').onclick=()=>change(()=>{const id=uid();s.sessions.push({...DEFAULT_TRAINING,id,mentor:0,learner:2,skill:0,start:8,duration:4});s.selected=id;});$('#remove').onclick=()=>change(()=>s.sessions=s.sessions.filter(x=>x.id!==s.selected));
document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>change(()=>{s.sessions=template(b.dataset.template);s.selected=s.sessions[0]?.id||null;},'Coaching plan replaced; Undo brings it back. Pinned plan and conditions kept.'));
$('#scenario').onchange=event=>{const v=event.target.value;change(()=>{s.scenario=v;s.workload=workloadFor(v);},'Demand preset changed for both plans. Absences kept.');};$('#change-week').onchange=event=>change(()=>s.workload.changeWeek=+event.target.value);
$('#demand').onchange=event=>{const {demand,skill}=event.target.dataset;if(demand)change(()=>s.workload[demand][+skill]=+event.target.value);};$('#add-absence').onclick=()=>change(()=>s.absences.push({id:uid(),person:2,from:16,to:18}));$('#absences').onchange=event=>{const {away,field}=event.target.dataset;if(away)change(()=>{const a=s.absences.find(x=>x.id===away);a[field]=+event.target.value;if(field==='from')a.to=Math.max(a.to,a.from);});};$('#absences').onclick=event=>{const id=event.target.closest('[data-remove-away]')?.dataset.removeAway;if(id)change(()=>s.absences=s.absences.filter(a=>a.id!==id));};
$('#week').oninput=event=>{s.week=+event.target.value;week();};$('#week').onchange=save;$('#pin').onclick=()=>change(()=>s.baseline=pin(s),'Plan pinned. All later demand and absence changes apply to both plans.');$('#undo').onclick=()=>{if(past.length){s=past.pop();compute();render();status('Last change undone.');save();}};$('#reset').onclick=()=>change(()=>{const baseline=s.baseline;s=initial();s.baseline=baseline;},'Default plan restored; pinned plan kept.');
$('#decision').onchange=event=>{const v=event.target.value;change(()=>s.decision=v,'Decision note saved.');};
let drag=null;const schedule=$('#schedule');schedule.onpointerdown=event=>{const b=event.target.closest('[data-period]');if(!b||event.button!==0)return;const p=s.sessions.find(x=>x.id===b.dataset.period);drag={id:p.id,x:event.clientX,start:p.start,next:p.start,width:b.parentElement.clientWidth,scroll:schedule.scrollLeft};schedule.setPointerCapture(event.pointerId);};schedule.onpointermove=event=>{if(!drag)return;const p=s.sessions.find(x=>x.id===drag.id);drag.next=Math.max(1,Math.min(25-p.duration,drag.start+Math.round((event.clientX-drag.x+schedule.scrollLeft-drag.scroll)/drag.width*24)));const b=document.getElementById('period-'+drag.id);b.style.left=(drag.next-1)/24*100+'%';b.textContent=`W${drag.next}–${drag.next+p.duration-1}`;};schedule.onpointerup=event=>{if(!drag)return;const d=drag;drag=null;schedule.releasePointerCapture(event.pointerId);if(d.next!==d.start)change(()=>{s.selected=d.id;s.sessions.find(x=>x.id===d.id).start=d.next;});else{s.selected=d.id;render();save();}document.getElementById('period-'+d.id)?.focus({preventScroll:true});};schedule.onpointercancel=()=>{drag=null;render();};schedule.onkeydown=event=>{const b=event.target.closest('[data-period]');if(!b)return;if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();change(()=>{s.selected=b.dataset.period;const p=s.sessions.find(x=>x.id===s.selected);p.start=Math.max(1,Math.min(25-p.duration,p.start+(event.key==='ArrowRight'?1:-1)));});}else if(['Enter',' '].includes(event.key)){event.preventDefault();s.selected=b.dataset.period;render();save();$('#mentor').focus();}};
$('#export').onclick=()=>downloadText('knowledge-plan.md',markdown(s),'text/markdown');$('#json').onclick=()=>downloadText('knowledge-plan.json',portable(s),'application/json');$('#import').onclick=()=>$('#file').click();$('#file').onchange=async event=>{const f=event.target.files?.[0];if(!f)return;try{if(f.size>1000000)throw Error('Choose a file under 1 MB.');const next=parse(await f.text());change(()=>s=next,'Experiment imported. Undo restores the previous plan.');}catch(error){status(error.message);}event.target.value='';};
$('#recover').onclick=()=>downloadText('knowledge-recovery.json',recovery||JSON.stringify(s),'application/json');$('#resume').onclick=()=>{paused=false;recovery=null;render();status('This plan saved in this browser.');save();};window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue!==JSON.stringify(s)){paused=true;recovery=event.newValue;status('Another tab changed saved work. Saving here is paused.');}});window.addEventListener('pagehide',()=>{s.decision=$('#decision').value;save();});compute();render();if(paused)status('Saved work needs recovery. Saving is paused; download a copy before replacing it.');
